mapper.select:

SELECT #{push} AS time,proto_type AS type,SUM(c2s_byte_len+s2c_byte_len) AS count
FROM traffic_protocol_statistic
  WHERE stat_time >= #{start}
  AND stat_time < #{end}
GROUP BY type;


SELECT #{push} AS time,proto_type AS type,MAX(link_num) AS linknum ,SUM(c2s_pkt_num+s2c_pkt_num) AS pakeagenum,
        SUM(c2s_byte_len+s2c_byte_len) AS bytes
FROM traffic_protocol_statistic
WHERE stat_time >= #{start}
    AND stat_time < #{end}
GROUP BY type


SELECT #{push} AS time ,ip_addr AS ip,area_id AS area,MAX(link_num) AS links,SUM(c2s_pkt_num+s2c_pkt_num) AS packets,SUM(c2s_byte_len+s2c_byte_len) AS bytes
FROM traffic_ip_active_statistic
WHERE stat_time >= #{start}
    AND stat_time < #{end}
GROUP BY ip,area


        SELECT #{push} AS time,t.port AS port ,MAX(t.speed) AS bps
        FROM ( SELECT RECV_TIME,PORT_DESC AS port,(INOCTETS_SPEED+OUTOCTETS_SPEED) AS speed
               FROM traffic_netflow_port_info
               WHERE RECV_TIME >= #{start}
			       AND RECV_TIME < #{end} ) t
         GROUP BY port;
